facts.command_line:
awk 
            BEGIN {
                split( ENVIRON["dc_directives"], directives, "[ \t]" );
            }
            {
                written = 0;
                for ( i in directives )
                   {
                       regex = "^[ \t]*" directives[i] "=";
                       if ( ( $0 ~ regex ) && ( ! written ) )
                           {
                               # Add single quotes (\0x27) around the value.
                               print directives[i] "=\x27" ENVIRON[directives[i]] "\x27";
                               written = 1;
                               break;
                           }
                   }
                   if ( ! written )
                       print $0;
            }

awk 
BEGIN   {
        minus_e = "";
        minus_D = "";
        minus_f = "";
        minus_b = "";
        rest = 0;
} {
        if (length($0) < 1) { next; }
        if (match($0, "^\\s*#")) { next; }
        if (match($0, "^\\s*-e")) { minus_e = $0; next; }
        if (match($0, "^\\s*-D\\s*$")) { minus_D = $0; next; }
        if (match($0, "^\\s*-f")) { minus_f = $0; next; }
        if (match($0, "^\\s*-b")) { minus_b = $0; next; }
        rules[rest++] = $0;
}
END     {
        printf "%s\n%s\n%s\n", minus_D, minus_b, minus_f;
        for (i = 0; i < rest; i++) { printf "%s\n", rules[i]; }
        printf "%s\n", minus_e;
}
